def experiment(inputs):
    import random
    seed = inputs.get('seed', 42)
    results = []
    for _ in range(5):
        # Force reset state
        random.seed(seed)
        results.append(random.random())
    divergence = 0.0 if len(set(results)) == 1 else 1.0
    return {'measurements': {'divergence_score': [divergence]}}
